param(
    [string]$ProjectRoot = (Get-Location).Path
)

$ErrorActionPreference = "Stop"

function Write-Step([string]$Message) {
    Write-Host ""
    Write-Host "==> $Message" -ForegroundColor Cyan
}

function Backup-File([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Required file not found: $Path"
    }

    $backupPath = "$Path.before-lint-fix"
    if (-not (Test-Path -LiteralPath $backupPath)) {
        Copy-Item -LiteralPath $Path -Destination $backupPath -Force
        Write-Host "Backup: $backupPath" -ForegroundColor DarkGray
    } else {
        Write-Host "Backup already exists: $backupPath" -ForegroundColor DarkGray
    }
}

function Replace-TextStrict {
    param(
        [string]$Path,
        [string]$OldText,
        [string]$NewText,
        [string]$Description
    )

    $content = Get-Content -LiteralPath $Path -Raw
    if (-not $content.Contains($OldText)) {
        Write-Host "Skipped (already fixed or source differs): $Description" -ForegroundColor Yellow
        return
    }

    $updated = $content.Replace($OldText, $NewText)
    Set-Content -LiteralPath $Path -Value $updated -Encoding utf8
    Write-Host "Fixed: $Description" -ForegroundColor Green
}

Write-Step "Checking project root"
$packagePath = Join-Path $ProjectRoot "package.json"
if (-not (Test-Path -LiteralPath $packagePath)) {
    throw "package.json was not found in: $ProjectRoot"
}

$embeddedFiles = @{
    "src/app/admin/dashboard/page.tsx" = ""
    "src/components/layout/app-shell.tsx" = ""
    "src/components/maps/vulnerable-map.tsx" = ""
}

Write-Step "Replacing the three complete files"
foreach ($relativePath in $embeddedFiles.Keys) {
    $target = Join-Path $ProjectRoot $relativePath
    Backup-File $target
    $bytes = [Convert]::FromBase64String($embeddedFiles[$relativePath])
    [System.IO.File]::WriteAllBytes($target, $bytes)
    Write-Host "Replaced: $relativePath" -ForegroundColor Green
}

$leafletMap = Join-Path $ProjectRoot "src/components/map/VulnerableMap.tsx"
Write-Step "Fixing online-state handling"
Backup-File $leafletMap

Replace-TextStrict `
    -Path $leafletMap `
    -OldText "  const [isOnline, setIsOnline] = useState(true)" `
    -NewText @'
  const [isOnline, setIsOnline] = useState(() => {
    return typeof navigator === 'undefined' ? true : navigator.onLine
  })
'@.TrimEnd() `
    -Description "lazy online-state initialization"

$oldOnlineEffect = @'
  useEffect(() => {
    if (typeof navigator !== 'undefined') {
      setIsOnline(navigator.onLine)
    }

    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])
'@

$newOnlineEffect = @'
  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])
'@

Replace-TextStrict `
    -Path $leafletMap `
    -OldText $oldOnlineEffect.TrimEnd() `
    -NewText $newOnlineEffect.TrimEnd() `
    -Description "online/offline event subscription"

$approvalCenter = Join-Path $ProjectRoot "src/components/admin/approval-center.tsx"
Write-Step "Fixing approval-center selection code"
Backup-File $approvalCenter

Replace-TextStrict `
    -Path $approvalCenter `
    -OldText "      checked ? next.add(id) : next.delete(id)" `
    -NewText @'
      if (checked) {
        next.add(id)
      } else {
        next.delete(id)
      }
'@.TrimEnd() `
    -Description "single-record selection"

Replace-TextStrict `
    -Path $approvalCenter `
    -OldText "        checked ? next.add(id) : next.delete(id)" `
    -NewText @'
        if (checked) {
          next.add(id)
        } else {
          next.delete(id)
        }
'@.TrimEnd() `
    -Description "visible-record selection"

$directiveFiles = @(
    (Join-Path $ProjectRoot "balanced-wow-ui-overlay/src/components/maps/location-picker.tsx"),
    (Join-Path $ProjectRoot "src/components/maps/location-picker.tsx"),
    (Join-Path $ProjectRoot "src/components/profile-view.tsx")
)

Write-Step "Removing obsolete ESLint suppression comments"
foreach ($file in $directiveFiles) {
    if (Test-Path -LiteralPath $file) {
        Backup-File $file
        $content = Get-Content -LiteralPath $file -Raw
        $updated = [regex]::Replace(
            $content,
            "(?m)^[ \t]*//[ \t]*eslint-disable-next-line[ \t]+react-hooks/exhaustive-deps[ \t]*\r?\n",
            ""
        )
        Set-Content -LiteralPath $file -Value $updated -Encoding utf8
        Write-Host "Cleaned: $file" -ForegroundColor Green
    } else {
        Write-Host "Skipped missing optional file: $file" -ForegroundColor Yellow
    }
}

Write-Step "Adding package scripts"
Backup-File $packagePath
$package = Get-Content -LiteralPath $packagePath -Raw | ConvertFrom-Json
if ($null -eq $package.scripts) {
    $package | Add-Member -MemberType NoteProperty -Name scripts -Value ([ordered]@{})
}

$package.scripts | Add-Member -MemberType NoteProperty -Name "lint:fix" -Value "eslint . --fix" -Force
$package.scripts | Add-Member -MemberType NoteProperty -Name "typecheck" -Value "tsc --noEmit" -Force
$package.scripts | Add-Member -MemberType NoteProperty -Name "check" -Value "bun run lint && bun run typecheck && bun run build" -Force
$package | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $packagePath -Encoding utf8
Write-Host "Updated: package.json" -ForegroundColor Green

Write-Step "All fixes applied"
Write-Host "Now run:" -ForegroundColor White
Write-Host "  bun run lint:fix"
Write-Host "  bun run lint"
Write-Host "  bun run typecheck"
Write-Host "  bun run build"
